import React from 'react';
import { NavLink } from 'react-router-dom';
import '../styles/Background.css';
import logo from '../assets/logo.png';

const Background = ({ children }) => {
    return (
        <div className="background-container">
            {/* Background shapes */}
            <div className="background-shapes">
                <div className="shape-yellow-circle"></div>
                <div className="shape-blue-large"></div>
                <div className="shape-purple-overlay"></div>
                <div className="shape-pink-bottom"></div>
            </div>

            {/* Navbar */}
            <nav className="navbar">
                <div className="navbar-container">
                    <div className="logo-section">
                        <NavLink to="/">
                            <img src={logo} alt="Logo" className="logo-image" />
                        </NavLink>
                    </div>

                    <div className="menu-items">
                        <NavLink to="/gioithieu" className={({ isActive }) => isActive ? 'menu-link active' : 'menu-link'}>Giới thiệu</NavLink>
                        <NavLink to="/pages" className={({ isActive }) => isActive ? 'menu-link active' : 'menu-link'}>Bài viết</NavLink>
                        <NavLink to="/marketplace" className={({ isActive }) => isActive ? 'menu-link active' : 'menu-link'}>Marketplace</NavLink>
                        <NavLink to="/customerForm" className={({ isActive }) => isActive ? 'menu-link active' : 'menu-link'}>Liên hệ</NavLink>
                    </div>

                    <select className="language-selector">
                        <option>Tiếng Việt</option>
                        <option>English</option>
                    </select>
                </div>
            </nav>

            {/* Main Content */}
            <div className="main-content">
                <div className="content-wrapper">
                    {children}
                </div>
            </div>
        </div>
    );
};

export default Background;
